gni(){return"\u041d\u043e\u0432\u0430\u044f \u043f\u0430\u043f\u043a\u0430"},
gzn(){return"\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u043f\u0430\u043f\u043a\u0438"},
gzh(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u044d\u043c\u043e\u0434\u0437\u0438"},
