gzj(){return"\u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e)"},
gzo(){return"\u041d\u0435\u0434\u0430\u0432\u043d\u043e \u043f\u0440\u043e\u0441\u043b\u0443\u0448\u0430\u043d\u043e"},
gzf(){return"\u0421\u043e\u0437\u0434\u0430\u0442\u044c"},
gzk(){return"\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u043f\u0430\u043f\u043a\u0443"},
gq7(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c"},
gzi(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u044d\u0442\u0443 \u043f\u0430\u043f\u043a\u0443? \u0422\u0440\u0435\u043a\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u0431\u0443\u0434\u0443\u0442 \u0432 \u043d\u0435\u0439 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u044b."},
gzd(){return"\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0432 \u043f\u0430\u043f\u043a\u0443"},
gzl(){return"\u042d\u043c\u043e\u0434\u0437\u0438"},
gze(){return"\u0426\u0432\u0435\u0442"},
gq8(){return"\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c"},
gzm(){return"\u042d\u0442\u0430 \u043f\u0430\u043f\u043a\u0430 \u043f\u0443\u0441\u0442\u0430. \u0423\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u0435\u0440\u0434\u0446\u0435 \u0443 \u0442\u0440\u0435\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0433\u043e \u0441\u044e\u0434\u0430."},
